    (179, 'unified_sites', 'thumbnail_url', 'c40df04b-563c-45b1-80db-82e646445531', 'c40df04b-563c-45b1-80db-82e646445531'::uuid, '/data/images/wiki/c40df04b/hero.webp', '/data/images/wiki/c40df04b/Segsbury_Camp_ditch.webp', 'import-hero-rollback:unified_sites.thumbnail_url:c40df04b-563c-45b1-80db-82e646445531', 'rollback of import-hero chunk 003: unified_sites.thumbnail_url on c40df04b-563c-45b1-80db-82e646445531 returned to ''/data/images/wiki/c40df04b/hero.webp'' -> ''/data/images/wiki/c40df04b/Segsbury_Camp_ditch.webp''', '[{"quote": "import-hero:unified_sites.thumbnail_url:c40df04b-563c-45b1-80db-82e646445531: ''/data/images/wiki/c40df04b/Segsbury_Camp_ditch.webp'' -> ''/data/images/wiki/c40df04b/hero.webp''", "source": "remediation_change_log (the row this undoes)", "url": "remediation_change_log.run_stamp=import-hero-2026-10-06-004-003"}]'::jsonb),
