CREATE TEMP TABLE _img_may_empty (site_id UUID PRIMARY KEY) ON COMMIT DROP;
INSERT INTO _img_may_empty (site_id) VALUES ('ad16f637-fa0c-4920-bfae-7a53dee2593a'::uuid), ('b6aab229-8793-40ad-a697-c8dbf6e331bf'::uuid), ('b8aedc17-2215-44c3-b89c-8125050efbd5'::uuid);

CREATE TEMP TABLE _img_live_before ON COMMIT DROP AS
  SELECT DISTINCT w.site_id FROM wiki_images w
   WHERE w.site_id IN (SELECT site_id FROM _img_plan) AND w.is_excluded IS NOT TRUE;

DO $$
DECLARE
    bad      integer;
    moved    integer := 0;
    expected integer := 186;
    r        RECORD;
BEGIN
    -- guard 1: every planned site is a curated site (the source is a RAISE argument, never
    -- part of the quoted message)
    SELECT count(*) INTO bad FROM (SELECT DISTINCT site_id FROM _img_plan) p
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned site(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- guard 2: every planned image row exists and lives on the site the plan names
    SELECT count(*) INTO bad FROM _img_plan p
      LEFT JOIN wiki_images w ON w.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND (w.id IS NULL OR w.site_id IS DISTINCT FROM p.site_id);
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned image row(s) do not live on the site the plan names', bad;
    END IF;

    -- guard 3: every planned row still holds the planned old value (NULL-safe)

    SELECT count(*) INTO bad FROM _img_plan p JOIN unified_sites t ON t.id = CASE WHEN p.table_name = 'unified_sites' THEN p.row_key::uuid END
     WHERE p.table_name = 'unified_sites' AND p.column_name = 'thumbnail_url'
       AND t.thumbnail_url::text IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned thumbnail_url row(s) no longer hold the planned old value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'file_size_bytes'
       AND t.file_size_bytes::text IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned file_size_bytes row(s) no longer hold the planned old value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'filename'
       AND t.filename::text IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned filename row(s) no longer hold the planned old value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'height'
       AND t.height::text IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned height row(s) no longer hold the planned old value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'is_excluded'
       AND t.is_excluded::text IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned is_excluded row(s) no longer hold the planned old value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'is_hero'
       AND t.is_hero::text IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned is_hero row(s) no longer hold the planned old value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'title'
       AND t.title::text IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned title row(s) no longer hold the planned old value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'width'
       AND t.width::text IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned width row(s) no longer hold the planned old value', bad;
    END IF;

    -- the only writer
    FOR r IN SELECT * FROM _img_plan ORDER BY seq LOOP
        moved := moved + apply_remediation_change(
            r.table_name, r.column_name, 'id', r.row_key, r.old_value, r.new_value,
            'import-hero/owner-2026-10-05', 'import-hero-2026-10-06-004-003-rollback', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;
    IF moved <> expected THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds its new value

    SELECT count(*) INTO bad FROM _img_plan p JOIN unified_sites t ON t.id = CASE WHEN p.table_name = 'unified_sites' THEN p.row_key::uuid END
     WHERE p.table_name = 'unified_sites' AND p.column_name = 'thumbnail_url'
       AND t.thumbnail_url::text IS DISTINCT FROM p.new_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned thumbnail_url row(s) do not hold the new value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'file_size_bytes'
       AND t.file_size_bytes::text IS DISTINCT FROM p.new_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned file_size_bytes row(s) do not hold the new value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'filename'
       AND t.filename::text IS DISTINCT FROM p.new_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned filename row(s) do not hold the new value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'height'
       AND t.height::text IS DISTINCT FROM p.new_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned height row(s) do not hold the new value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'is_excluded'
       AND t.is_excluded::text IS DISTINCT FROM p.new_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned is_excluded row(s) do not hold the new value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'is_hero'
       AND t.is_hero::text IS DISTINCT FROM p.new_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned is_hero row(s) do not hold the new value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'title'
       AND t.title::text IS DISTINCT FROM p.new_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned title row(s) do not hold the new value', bad;
    END IF;

    SELECT count(*) INTO bad FROM _img_plan p JOIN wiki_images t ON t.id = CASE WHEN p.table_name = 'wiki_images' THEN p.row_key::integer END
     WHERE p.table_name = 'wiki_images' AND p.column_name = 'width'
       AND t.width::text IS DISTINCT FROM p.new_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned width row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: plan -> journal, row for row, with the planned values and keys
    SELECT count(*) INTO bad FROM _img_plan p
      LEFT JOIN remediation_change_log l
        ON l.run_stamp = 'import-hero-2026-10-06-004-003-rollback' AND l.table_name = p.table_name
       AND l.column_name = p.column_name AND l.row_pk = p.row_key
     WHERE l.id IS NULL OR l.old_value IS DISTINCT FROM p.old_value
        OR l.new_value IS DISTINCT FROM p.new_value OR l.change_key IS DISTINCT FROM p.change_key;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % planned row(s) disagree with the journal', bad;
    END IF;

    -- invariant 3: journal -> plan: this run stamp journalled the planned rows and nothing else
    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'import-hero-2026-10-06-004-003-rollback'
       AND NOT EXISTS (SELECT 1 FROM _img_plan p
                        WHERE p.table_name = l.table_name AND p.column_name = l.column_name
                          AND p.row_key = l.row_pk);
    IF bad > 0 OR (SELECT count(*) FROM remediation_change_log WHERE run_stamp = 'import-hero-2026-10-06-004-003-rollback') <> expected THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: the journal of this run stamp is not the plan (% unplanned row(s))', bad;
    END IF;

    -- invariant 4: at most one hero per touched site
    -- the invariant the repair must leave behind: at most one hero per touched site
    -- (DISTINCT: _img_plan holds several rows per site, and a plain join would count each
    --  hero row twice - the check would then fail on a correct repair)
    SELECT count(*) INTO bad FROM (
        SELECT s.site_id FROM (SELECT DISTINCT site_id FROM _img_plan) s
          JOIN wiki_images w ON w.site_id = s.site_id
         GROUP BY s.site_id HAVING count(*) FILTER (WHERE w.is_hero) > 1) x;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % touched site(s) end with more than one hero', bad;
    END IF;

    -- invariant 5: no hero on an excluded row of a touched site
    SELECT count(*) INTO bad FROM wiki_images w
     WHERE w.site_id IN (SELECT site_id FROM _img_plan) AND w.is_hero AND w.is_excluded IS TRUE;
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % hero row(s) are excluded', bad;
    END IF;

    -- invariant 6: a touched site that had a live image still has one, unless the chunk names it
    SELECT count(*) INTO bad FROM _img_live_before b
     WHERE NOT EXISTS (SELECT 1 FROM wiki_images w
                        WHERE w.site_id = b.site_id AND w.is_excluded IS NOT TRUE)
       AND b.site_id NOT IN (SELECT site_id FROM _img_may_empty);
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % site(s) lost their last live image', bad;
    END IF;

    -- invariant 7: every image kind of a touched row is in migration 0019's vocabulary
    SELECT count(*) INTO bad FROM wiki_images w
     WHERE w.site_id IN (SELECT site_id FROM _img_plan)
       AND w.image_kind IS NOT NULL AND w.image_kind NOT IN ('artifact', 'map_or_document', 'other', 'painting_or_artwork', 'people', 'site_photo', 'unknown');
    IF bad > 0 THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-004 - the import image takes the hero flag rollback chunk 003: % image kind(s) outside the vocabulary', bad;
    END IF;
END $$;

SELECT 'journal rows for this run', count(*)::text FROM remediation_change_log WHERE run_stamp = 'import-hero-2026-10-06-004-003-rollback';
SELECT 'planned rows', count(*)::text FROM _img_plan;
COMMIT;
